<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$role=$user['role'];$s=$agreement['status'];$canOps=in_array($role,['system_admin','front_desk'],true);$canTrip=in_array($role,['system_admin','front_desk','fleet_manager'],true);$canFinance=in_array($role,['system_admin','finance_staff'],true); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agreement #<?= (int)$agreement['agreement_id'] ?> | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"><script src="/assets/js/rentals.js" defer></script></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/rentals">Agreements</a><a href="/staff/notifications">Notifications</a></nav></header><main class="page-shell"><section class="page-heading"><div><p class="eyebrow">Rental agreement #<?= (int)$agreement['agreement_id'] ?></p><h1><?= $e($agreement['customer_name']) ?> · <?= $e($agreement['plate_number']) ?></h1><p>Status <strong><?= $e($s) ?></strong> · <?= $e($agreement['start_date']) ?> to <?= $e($agreement['end_date']) ?> · <?= (int)$agreement['rental_days'] ?> day(s)</p></div></section><?php if($notice):?><p class="alert" role="status"><?= $e($notice) ?></p><?php endif;?><section class="panel"><h2>Cost summary</h2><p>Base ₱<?= $e($agreement['base_amount']) ?> · Charges/discounts ₱<?= $e(number_format((float)$total-(float)$agreement['base_amount'],2)) ?> · Billable total ₱<?= $e($total) ?></p><p>Deposit ₱<?= $e($agreement['security_deposit_amount']) ?> — <?= $e($agreement['deposit_status']) ?></p><p>Pickup <?= $e($agreement['scheduled_pickup_at']??'not set') ?> UTC · return <?= $e($agreement['scheduled_return_at']??'not set') ?> UTC</p><?php if($canOps):?><form method="post" action="/rentals/link"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><button type="submit">Send booking-management link</button></form><?php endif;?></section>
<section class="panel"><h2>Lifecycle</h2><div class="button-row"><?php if($canOps&&$s==='reserved'):?><form method="post" action="/rentals/action"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="action" value="confirm"><button>Confirm</button></form><?php endif;?><?php if($canTrip&&$s==='confirmed'):?><form method="post" action="/rentals/action"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="action" value="pickup"><button>Record pickup</button></form><?php endif;?><?php if($canTrip&&$s==='active'):?><form method="post" action="/rentals/action"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="action" value="return"><button>Record return</button></form><?php endif;?><?php if($canFinance&&$s==='returned'):?><form method="post" action="/rentals/action"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="action" value="complete"><button>Complete after reconciliation</button></form><?php endif;?><?php if($canOps&&in_array($s,['reserved','confirmed'],true)):?><form method="post" action="/rentals/action" class="reason-action"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="action" value="cancel"><label>Cancellation reason<input name="reason" maxlength="500" required></label><button>Cancel</button></form><?php if($agreement['scheduled_pickup_at']!==null):?><form method="post" action="/rentals/action" class="reason-action"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="action" value="no_show"><label>No-show reason<input name="reason" maxlength="500" required></label><button>Mark no-show</button></form><?php endif;?><?php endif;?></div><h3>Agreement history</h3><div class="table-wrap"><table><thead><tr><th>UTC timestamp</th><th>From</th><th>To</th><th>Reason</th><th>Actor</th></tr></thead><tbody><?php foreach($statusHistory as $h):?><tr><td><?= $e($h['created_at']) ?></td><td><?= $e($h['old_status']??'—') ?></td><td><?= $e($h['new_status']) ?></td><td><?= $e($h['reason']??'—') ?></td><td><?= $e($h['actor_email']) ?></td></tr><?php endforeach;?></tbody></table></div><p class="muted">Return condition and damage capture belong to M7. Overdue active rentals remain active and are surfaced in M10 reporting.</p></section>
<section class="panel"><h2>Charges</h2><div class="table-wrap"><table><thead><tr><th>Type</th><th>Entry</th><th>Amount</th><th>Description</th><th>When / by</th><th></th></tr></thead><tbody><?php foreach($charges as $c):?><tr><td><?= $e($c['charge_type']) ?></td><td><?= $e($c['entry_kind']) ?></td><td>₱<?= $e($c['amount']) ?></td><td><?= $e($c['description']) ?></td><td><?= $e($c['created_at'].' / '.$c['actor_email']) ?></td><td><?php if($canFinance&&$c['entry_kind']==='charge'):?><form method="post" action="/rentals/charge/reverse" class="inline-form"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><input type="hidden" name="charge_id" value="<?= (int)$c['charge_id'] ?>"><input name="reason" maxlength="490" placeholder="Reversal reason" required><button>Reverse</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$charges):?><tr><td colspan="6">No additional charges.</td></tr><?php endif;?></tbody></table></div><?php if($canFinance&&!in_array($s,['completed','cancelled','no_show'],true)):?><form method="post" action="/rentals/charge" class="form-grid"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><label>Type<select name="charge_type"><option>fee</option><option>discount</option><option>tax</option><option>damage</option><option>other</option></select></label><label>Amount (₱)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Description<input name="description" maxlength="500" required></label><button>Add charge</button></form><?php endif;?></section>
<section class="panel"><h2>Deposit history</h2><div class="table-wrap"><table><thead><tr><th>UTC</th><th>From</th><th>To</th><th>Amount</th><th>Reason</th><th>Actor</th></tr></thead><tbody><?php foreach($depositHistory as $d):?><tr><td><?= $e($d['created_at']) ?></td><td><?= $e($d['old_status']??'—') ?></td><td><?= $e($d['new_status']) ?></td><td><?= $e($d['old_amount']??'—') ?> → <?= $e($d['new_amount']) ?></td><td><?= $e($d['reason']) ?></td><td><?= $e($d['actor_email']) ?></td></tr><?php endforeach;?></tbody></table></div><?php if($canFinance&&!in_array($s,['completed','cancelled','no_show'],true)):?><form method="post" action="/rentals/deposit" class="form-grid"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="agreement_id" value="<?= (int)$agreement['agreement_id'] ?>"><label>Deposit status<select name="deposit_status"><?php foreach(['not_required','due','held','released','refunded','forfeited'] as $ds):?><option value="<?= $e($ds) ?>"<?= $agreement['deposit_status']===$ds?' selected':'' ?>><?= $e($ds) ?></option><?php endforeach;?></select></label><label>Amount (₱)<input name="amount" type="number" min="0" step="0.01" value="<?= $e($agreement['security_deposit_amount']) ?>" required></label><label>Reason<input name="reason" maxlength="500" required></label><button>Record deposit change</button></form><?php endif;?></section></main></body></html>
